g = primitives.call(name="ground_robocasa365_visual_target", entity_name="obj")
if g.ok:
    for yaw in [0.5, -0.5, 0.0]:
        a = primitives.call(name="grasp_robocasa365_object", object_name="obj", evidence_handles=[g.output["evidence_handle"]], grasp_approach="center", grasp_wrist_yaw_offset_rad=yaw, gripper_command=1.0, horizon=100)
        print(a.ok, a.output)
        if a.ok and a.output.get("held_object_handle"):
            held = a.output["held_object_handle"]
            t = primitives.call(name="ground_robocasa365_visual_target", entity_name="container")
            if t.ok:
                m = primitives.call(name="move_robocasa365_ee_to", target_name="container", offset=[0.0,-0.07,0.22], evidence_handles=[t.output["evidence_handle"]], gripper_command=1.0, horizon=100)
                print(m.ok, m.output)
            break
        g = primitives.call(name="ground_robocasa365_visual_target", entity_name="obj")
        if not g.ok:
            break
raise Exception(str(a.output))

t = primitives.call(name="ground_robocasa365_visual_target", entity_name="container")
if t.ok:
    p = primitives.call(name="place_robocasa365_object_at", object_name="obj", target_name="container", relation="on", evidence_handles=[t.output["evidence_handle"]], held_object_handle=held, gripper_command=1.0, horizon=150, offset=[0.0,-0.06,0.08])
    print(p.ok, p.output)
s = primitives.call(name="observe_robocasa365_kitchen_state")
if s.ok:
    raise Exception(str(s.output["objects"]))
else:
    print(s.ok, s.output)

